set-variable.value:
@{
            var jwt = (Jwt)context.Variables["jwt"];
            string oid = jwt.Claims.GetValueOrDefault("oid",  string.Empty);
            return oid.ToLowerInvariant();
        }

@{
            var jwt = (Jwt)context.Variables["jwt"];
            return jwt.Claims.GetValueOrDefault("tid", "unknown");
        }

@{
            var jwt = (Jwt)context.Variables["jwt"];
            return jwt.Claims.GetValueOrDefault("azp",
                   jwt.Claims.GetValueOrDefault("appid",
                   context.Subscription?.Id ?? "unknown"));
        }

@{
    var jwt = (Jwt)context.Variables["jwt"];
    // v1 tokens: unique_name / upn; v2 tokens: preferred_username
    return jwt.Claims.GetValueOrDefault("preferred_username",
           jwt.Claims.GetValueOrDefault("upn",
           jwt.Claims.GetValueOrDefault("unique_name",
           jwt.Claims.GetValueOrDefault("email", "")))).ToLowerInvariant();
}

@{
    var jwt = (Jwt)context.Variables["jwt"];
    return jwt.Claims.GetValueOrDefault("name", "");
}

@{
            var jwt = (Jwt)context.Variables["jwt"];
            var tokenRoles = jwt.Claims.GetValueOrDefault("roles", string.Empty)
                .Split(","[0])
                .Select(role => role.Trim())
                .Where(role => !string.IsNullOrEmpty(role))
                .ToArray();
            var allowedRoles = "{{team-app-roles}}"
                .Split(","[0])
                .Select(role => role.Trim())
                .Where(role => !string.IsNullOrEmpty(role))
                .ToArray();
            var matches = allowedRoles
                .Where(allowed => tokenRoles.Any(role => string.Equals(role, allowed, StringComparison.OrdinalIgnoreCase)))
                .ToArray();
            return matches.Length == 1 ? matches[0] : matches.Length == 0 ? "" : "__multiple__";
        }

@{
    try {
        var body = context.Request.Body.As<string>(preserveContent: true);
        JObject.Parse(body);
        return body;
    } catch { return ""; }
}

@{
            var routeDeployment = context.Request.MatchedParameters.GetValueOrDefault("deployment-id", "");
            if (!string.IsNullOrEmpty(routeDeployment)) {
                return routeDeployment;
            }
            try {
                var body = JObject.Parse((string)context.Variables["requestBody"]);
                return (string)body["model"] ?? "unknown";
            } catch {
                return "unknown";
            }
        }

send-request.set-body:
@{
                return new JObject(
                    new JProperty("operationId", context.RequestId.ToString()),
                    new JProperty("callerKey", (string)context.Variables["callerKey"]),
                    new JProperty("teamRole", (string)context.Variables["teamRole"]),
                    new JProperty("userKey", (string)context.Variables["userKey"]),
                    new JProperty("userEmail", (string)context.Variables["userEmail"]),
                    new JProperty("userName", (string)context.Variables["userName"]),
                    new JProperty("appId", (string)context.Variables["appId"]),
                    new JProperty("deployment", (string)context.Variables["deploymentName"]),
                    new JProperty("period", "Monthly"),
                    new JProperty("currency", "USD"),
                    new JProperty("request", JObject.Parse((string)context.Variables["requestBody"]))
                ).ToString();
            }

when.condition:
@{
                var r = context.Variables.GetValueOrDefault<IResponse>("costReservationResponse");
                return r == null || r.StatusCode != 200;
            }

@{
                var r = context.Variables.GetValueOrDefault<IResponse>("costReservationResponse");
                try {
                    var b = r.Body.As<JObject>(preserveContent: true);
                    return (bool?)b["allowed"] != true || string.IsNullOrEmpty((string)b["reservationId"]);
                } catch { return true; }
            }

set-variable.value:
@{
            var r = (IResponse)context.Variables["costReservationResponse"];
            return (string)r.Body.As<JObject>(preserveContent: true)["reservationId"];
        }

@{
            var contentType = context.Response.Headers.GetValueOrDefault("Content-Type", "");
            if (contentType.IndexOf("text/event-stream", StringComparison.OrdinalIgnoreCase) >= 0) {
                return new JObject(new JProperty("state", "streaming_unsettled")).ToString();
            }
            try {
                var body = context.Response.Body.As<JObject>(preserveContent: true);
                var usage = body?["usage"] as JObject;
                var valid = usage != null
                    && (usage["prompt_tokens"] != null || usage["input_tokens"] != null)
                    && (usage["completion_tokens"] != null || usage["output_tokens"] != null);
                return new JObject(
                    new JProperty("state", valid ? "available" : "missing_usage"),
                    new JProperty("usage", usage),
                    new JProperty("model", body?["model"])
                ).ToString();
            } catch {
                return new JObject(new JProperty("state", "invalid_response")).ToString();
            }
        }

@{
            var usage = JObject.Parse((string)context.Variables["responseUsage"])["usage"] as JObject;
            return (int?)usage?["prompt_tokens"] ?? (int?)usage?["input_tokens"] ?? 0;
        }

@{
        var usage = JObject.Parse((string)context.Variables["responseUsage"])["usage"] as JObject;
        return (int?)usage?["completion_tokens"] ?? (int?)usage?["output_tokens"] ?? 0;
}

@{
        var usage = JObject.Parse((string)context.Variables["responseUsage"])["usage"] as JObject;
        return ((int?)usage?["cache_creation_input_tokens"]
             ?? (int?)usage?["cache_write_input_tokens"]
             ?? (int?)usage?["prompt_tokens_details"]?["cache_write_tokens"]
             ?? (int?)usage?["input_tokens_details"]?["cache_write_tokens"]
             ?? 0);
}

@{
        var usage = JObject.Parse((string)context.Variables["responseUsage"])["usage"] as JObject;
        return ((int?)usage?["cache_read_input_tokens"]
             ?? (int?)usage?["prompt_tokens_details"]?["cached_tokens"]
             ?? (int?)usage?["input_tokens_details"]?["cached_tokens"]
             ?? 0);
}

@{
        var usage = JObject.Parse((string)context.Variables["responseUsage"])["usage"] as JObject;
        var rawInput = ((int?)usage?["prompt_tokens"] ?? (int?)usage?["input_tokens"] ?? 0);
        if (usage?["cache_creation_input_tokens"] != null || usage?["cache_read_input_tokens"] != null) {
            return rawInput;
        }
        var cacheWrite = (int)context.Variables["cacheWriteTokens"];
        var cacheRead = (int)context.Variables["cacheReadTokens"];
        return Math.Max(0, rawInput - cacheWrite - cacheRead);
}

@{
        var response = JObject.Parse((string)context.Variables["responseUsage"]);
        return (string)response["model"] ?? (string)context.Variables["deploymentName"];
}

send-request.set-body:
@{
                return new JObject(
                    new JProperty("operationId", context.RequestId.ToString()),
                    new JProperty("deployment", (string)context.Variables["deploymentName"]),
                    new JProperty("model", (string)context.Variables["modelName"]),
                    new JProperty("inputTokens", (int)context.Variables["inputTokens"]),
                    new JProperty("cacheWriteTokens", (int)context.Variables["cacheWriteTokens"]),
                    new JProperty("cacheReadTokens", (int)context.Variables["cacheReadTokens"]),
                    new JProperty("outputTokens", (int)context.Variables["completionTokens"]),
                    new JProperty("status", context.Response.StatusCode)
                ).ToString();
            }

set-variable.value:
@{
            var response = context.Variables.GetValueOrDefault<IResponse>("costSettlementResponse");
            if (response == null) {
                return (string)context.Variables["usageState"];
            }
            if (response.StatusCode != 200) { return "settlement_failed"; }
            try {
                var body = response.Body.As<JObject>(preserveContent: true);
                return !string.IsNullOrEmpty((string)body["actualUsd"]) && !string.IsNullOrEmpty((string)body["remainingUsd"])
                    ? "settled" : "settlement_failed";
            } catch { return "settlement_failed"; }
        }

@{
            var response = context.Variables.GetValueOrDefault<IResponse>("costSettlementResponse");
            if (response == null || (string)context.Variables["settlementState"] != "settled") { return "{}"; }
            var breakdown = response.Body.As<JObject>(preserveContent: true)["spendBreakdown"] as JObject;
            return breakdown == null ? "{}" : breakdown.ToString();
        }

@{
            var response = context.Variables.GetValueOrDefault<IResponse>("costSettlementResponse");
            if (response == null || (string)context.Variables["settlementState"] != "settled") {
                return "unavailable";
            }
            try {
                return (string)response.Body.As<JObject>(preserveContent: true)["actualUsd"] ?? "unavailable";
            } catch { return "unavailable"; }
        }

@{
            var response = context.Variables.GetValueOrDefault<IResponse>("costSettlementResponse");
            if (response == null || (string)context.Variables["settlementState"] != "settled") {
                return "unavailable";
            }
            try {
                return (string)response.Body.As<JObject>(preserveContent: true)["remainingUsd"] ?? "unavailable";
            } catch { return "unavailable"; }
        }

return-response.set-body:
@{
                        return new JObject(
                            new JProperty("error", "rate_limit_or_quota_exceeded"),
                            new JProperty("source", context.LastError.Source),
                            new JProperty("policyId", context.LastError.PolicyId),
                            new JProperty("userId", context.Variables.GetValueOrDefault("userId","")),
                            new JProperty("appId",  context.Variables.GetValueOrDefault("appId",""))
                        ).ToString();
                    }
